let qIndex=0,selection=[],submitted=false,confidence='未记录',assisted=false,hintOpen=false,mockActive=false,mockIndex=0,mockAnswers={},mockFlags=new Set();
let importStep=0,importFixed=false,aiTask=null,aiApproved=false,aiRejected=false,actionChosen='补一条概念对照笔记',reviewRevealed=false,reviewRated='',projectType='大学课程',budgetMinutes=25,toastTimer;
