const go=(id,text,cls='quiet')=>`<button class="btn ${cls}" data-go="${id}">${text}</button>`;
const action=(id,text,cls='quiet',disabled=false)=>`<button class="btn ${cls}" data-action="${id}"${disabled?' disabled':''}>${text}</button>`;
const pill=(text,cls='')=>`<span class="pill ${cls}">${text}</span>`;
const head=(eye,title,desc,button='')=>`<div class="screen-head"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`;
const section=(title,body,button='')=>`<section class="card${title==='今天的三件事'?' task-list':''}"><div class="section-title"><h2>${title}</h2>${button}</div>${body}</section>`;
const metric=(title,value,description)=>`<div class="card metric"><div class="metric-label"><span>${title}</span>${icon(title.includes('笔记')?'note':title.includes('复测')?'clock':'chart')}</div><strong>${value}</strong><span class="muted">${description}</span></div>`;
const timeLabel=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
function toast(msg){clearTimeout(toastTimer);const e=document.getElementById('toast');e.textContent=msg;e.hidden=false;toastTimer=setTimeout(()=>e.hidden=true,4200);}
function closeDialog(){document.getElementById('dialog').close();}
function dialog(title,body,buttons){const d=document.getElementById('dialog');if(d.open)d.close();document.getElementById('dialog-body').innerHTML=`<h2 id="dialog-title">${title}</h2>${body}<div class="dialog-actions">${action('close-dialog','取消')}${buttons}</div>`;d.showModal();}
function save(){if(mode==='save-error'){noteSaved=false;toast('保存失败演示：草稿保留，请恢复保存后重试。');return false;}noteSaved=true;toast('演示：已保存到当前示例，未写入真实思源。');return true;}
function route(id,focus=true){if(!titles[id])id='home';if(mockActive&&id!=='mock'){setSidebar(false);history.replaceState(null,'','#mock');dialog('模考进行中','<p>交卷前保持作答条件。解析、资料学习和题目级 AI 暂不开放。</p><p class="muted small">你可以继续模考，或交卷后复盘。原型只演示插件内入口约束。</p>',action('finish-mock','交卷并复盘','primary'));return;}const changed=page!==id;page=id;if(location.hash!=='#'+id)history.replaceState(null,'','#'+id);setSidebar(false,false);render(changed);if(focus){document.getElementById('content').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function render(animate=false){const active=document.activeElement,focusId=active?.id,focusAction=active?.dataset.action;const group=groups.find(g=>g.pages.includes(page));document.querySelector('.project-switch').innerHTML='<span class="project-kicker">当前备考项目</span>'+esc(projectDraft.name)+'<small>'+esc(projectType)+' · 管理项目 ↗</small>'; document.getElementById('nav').innerHTML=groups.map(g=>`<button class="nav-btn${g===group?' active':''}" data-go="${g.pages[0]}"${g===group?' aria-current="page"':''}>${icon(g.icon)}${g.name}${g.name==='AI 任务'&&aiTask?'<span class="badge">1</span>':''}${g.pages.includes('wrongbook')?'<span class="badge">12</span>':''}</button>`).join('');document.getElementById('subnav').innerHTML=(group?.pages||['settings']).map(id=>`<button data-go="${id}"${id===page?' class="active" aria-current="page"':''}>${titles[id]}</button>`).join('');document.getElementById('breadcrumbs').innerHTML='<span class="crumb-project">'+esc(projectDraft.name)+'</span><span class="crumb-separator" aria-hidden="true">/</span><span class="crumb-current">'+esc(titles[page])+'</span>';updateSaveStatus();const messages={empty:'无资料演示：先添加你有权使用的资料，或使用原创样例。',offline:'离线演示：可以本地学习和记笔记；AI 与未可用的外部来源暂不可用。','save-error':'保存失败演示：本次草稿保留，确认保存后再退出。',stale:'来源更新演示：先核对新内容，历史作答仍保留当时版本。'};document.getElementById('state-message').innerHTML=mode==='ready'?'':`<div class="callout ${mode==='save-error'?'bad':'warn'}" style="margin-bottom:20px">${messages[mode]} ${mode==='save-error'?action('recover-save','恢复保存'):''}</div>`;document.getElementById('content').innerHTML=`<div class="screen${animate?' screen-enter':''}" id="screen-${page}">${screens[page]()}</div><p class="footnote">规划交互演示 · 页面不代表功能已实现；发布版能力与待验收范围见中文 README。</p>`;const target=focusId?document.getElementById(focusId):focusAction?document.querySelector('[data-action="'+CSS.escape(focusAction)+'"]'):null;if(target&&!target.disabled)target.focus({preventScroll:true});}
function updateSaveStatus(){const e=document.getElementById('save-status'),state=mode==='save-error'?'error':!noteSaved?'draft':mode==='offline'?'offline':'ready',text={error:'草稿待保存 · 演示',draft:'有未保存草稿 · 演示',offline:'本地继续 · 演示',ready:'本地示例就绪'}[state];e.dataset.state=state;if(e.textContent!==text)e.textContent=text;}
function setSidebar(open,restore=true){const nav=document.getElementById('sidebar'),wasOpen=nav.classList.contains('open');if(open&&!window.matchMedia('(max-width:850px)').matches)return;nav.classList.toggle('open',open);document.body.classList.toggle('nav-open',open);document.getElementById('menu').setAttribute('aria-expanded',String(open));document.getElementById('nav-backdrop').hidden=!open;document.querySelector('.workspace').inert=open;document.querySelector('.prototype-bar').inert=open;if(open){nav.setAttribute('role','dialog');nav.setAttribute('aria-modal','true');nav.querySelector('.brand').focus();}else{nav.removeAttribute('role');nav.removeAttribute('aria-modal');if(restore&&wasOpen)document.getElementById('menu').focus();}}
