const paletteCmd=[
  {g:'页面',icon:'home',label:'项目首页 · 今日该学什么',kw:'home 首页 目标 负载 连胜',run:()=>route('home')},
  {g:'页面',icon:'play',label:'独立作答 · 开始练习',kw:'practice 练习 刷题 作答',run:()=>route('practice')},
  {g:'页面',icon:'book',label:'错题本 · 重练与消灭进度',kw:'wrong 错题 重练',run:()=>route('wrongbook')},
  {g:'页面',icon:'clock',label:'模拟考试 · 配置一次演练',kw:'模考 mock 演练 试卷 蓝图',run:()=>route('mock-setup')},
  {g:'页面',icon:'chart',label:'学习证据报告',kw:'report 报告 统计 证据',run:()=>route('report')},
  {g:'页面',icon:'folder',label:'导入与校对',kw:'import 导入 excel csv gift aiken',run:()=>route('import')},
  {g:'页面',icon:'file',label:'题库与作者 · 浏览维护',kw:'bank 题库 浏览 编辑',run:()=>route('bank')},
  {g:'动作',icon:'spark',label:'AI 出题（当前上下文）',kw:'ai 出题 讲解',run:()=>route('ai')},
  {g:'动作',icon:'check',label:'切换深色 / 浅色主题',kbd:'T',kw:'theme 主题 深色 浅色 dark light',run:()=>setTheme(theme==='light'?'dark':'light')},
  {g:'动作',icon:'arrow',label:'重置示例数据',kw:'reset 重置 示例',run:()=>{location.hash='';location.reload();}},
];
const paletteEl=document.getElementById('palette'),paletteQ=document.getElementById('palette-q'),paletteList=document.getElementById('palette-list');
let paletteSel=0,paletteShown=[];
function paletteRender(){const q=paletteQ.value.trim();paletteShown=paletteCmd.filter(c=>!q||c.label.includes(q)||(c.kw||'').toLowerCase().includes(q.toLowerCase())||c.g.includes(q));if(paletteSel>=paletteShown.length)paletteSel=Math.max(0,paletteShown.length-1);let html='',lastG='';paletteShown.forEach((c,i)=>{if(c.g!==lastG){html+='<div class="palette-group">'+c.g+'</div>';lastG=c.g;}html+='<button class="palette-item'+(i===paletteSel?' sel':'')+'" data-palette="'+i+'">'+icon(c.icon)+'<span>'+c.label+'</span>'+(c.kbd?'<kbd>'+c.kbd+'</kbd>':'')+'</button>';});paletteList.innerHTML=html||'<p class="muted small" style="padding:14px">没有匹配的命令。试试「练习 / 模考 / 导入 / 报告」。</p>';}
function paletteOpen(){paletteEl.hidden=false;paletteQ.value='';paletteSel=0;paletteRender();paletteQ.focus();}
function paletteClose(){paletteEl.hidden=true;}
document.getElementById('palette-open').addEventListener('click',paletteOpen);
paletteEl.addEventListener('click',e=>{if(e.target===paletteEl)paletteClose();});
paletteList.addEventListener('click',e=>{const b=e.target.closest('[data-palette]');if(!b)return;const c=paletteShown[+b.dataset.palette];paletteClose();if(c)c.run();});
paletteQ.addEventListener('input',()=>{paletteSel=0;paletteRender();});
document.addEventListener('keydown',e=>{
  if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();paletteEl.hidden?paletteOpen():paletteClose();return;}
  if(paletteEl.hidden)return;
  if(e.key==='Escape'){e.preventDefault();paletteClose();return;}
  if(e.key==='ArrowDown'){e.preventDefault();paletteSel=Math.min(paletteSel+1,paletteShown.length-1);paletteRender();return;}
  if(e.key==='ArrowUp'){e.preventDefault();paletteSel=Math.max(paletteSel-1,0);paletteRender();return;}
  if(e.key==='Enter'){e.preventDefault();const c=paletteShown[paletteSel];if(c){paletteClose();c.run();}}
});

document.addEventListener('keydown',e=>{const nav=document.getElementById('sidebar');if(!nav.classList.contains('open'))return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();setSidebar(false);return;}if(e.key==='Tab'){const nodes=[...nav.querySelectorAll('a,button,input,select,textarea,[tabindex]')].filter(x=>!x.disabled&&x.tabIndex>=0&&x.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}e.stopImmediatePropagation();}});
function emptyPanel(){return `<section class="card empty"><span class="tile-icon" style="margin:auto">${icon('folder')}</span><h2>先选一小份有权使用的材料</h2><p class="muted">导入文件、手工录题或选笔记片段都可以；AI 是可选路径。</p><div class="row">${action('use-sample','使用原创样例','primary')}${go('import','看导入流程')}${go('bank','手工录题')}</div></section>`;}
